let score = 72;
if (score >= 80) {
  console.log('Lulus dengan kategori A');
} else if (score >= 60) {
  console.log('Lulus dengan kategori B');
} else {
  console.log('Belum lulus');
}

// Coba juga operator ==
const benar = (score == 72);
console.log('Apakah score sama dengan 72? ' + benar);

// Hitung jumlah 1 sampai N
let N = 5;
let total = 0;

for (let i = 1; i <= N; i++) {
  total = total + i;
}

console.log('N = ' + N);
console.log('Total dari 1 sampai ' + N + ' = ' + total);

// Bandingkan dengan while sederhana
let x = 1;
let totalWhile = 0;
while (x <= N) {
  totalWhile = totalWhile + x;
  x = x + 1;
}
console.log('Total (while) = ' + totalWhile);

function tambah(a, b) {
  return a + b;
}

function kali(a, b) {
  return a * b;
}

